<script setup lang="ts">
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import Icon from '@/components/ui/Icon.vue'
import UiButton from '@/components/ui/UiButton.vue'
import { formatSize } from '@/utils/bytes'
import { resourceColor, resourceThumbnail } from '@/utils/resourcePresentation'
export interface CardResource { id: string; name: string; creator?: string; version?: number; size_bytes?: number; resource_types?: string[] }
const props = defineProps<{ item: CardResource; image?: string | null; selected?: boolean; multiSelect?: boolean; checked?: boolean; disabled?: boolean; missing?: number; favorite?: boolean; canFavorite?: boolean; canLaunch?: boolean; loading?: boolean; landscape?: boolean; fresh?: boolean }>()
const emit = defineEmits<{ select: []; details: []; launch: []; favorite: []; toggle: [event: MouseEvent]; more: [event: MouseEvent]; imageError: [] }>()
const { t } = useI18n()
const type = computed(() => props.item.resource_types?.[0] || 'other')
</script>
<template><article class="package-card" :class="{ selected: selected || checked, landscape, loading, 'large-card': !landscape, 'small-card': landscape }" :style="{ '--thumb': resourceThumbnail(type), '--type-color': resourceColor(type) }" @contextmenu.prevent="emit('more', $event)"><div class="package-preview large-card-thumb small-card-thumb"><img v-if="image && !loading" data-resource-preview :src="image" :alt="item.name" loading="lazy" @error="emit('imageError')" /><Icon v-else-if="!loading" name="image" :size="34" class="image-placeholder" /></div><div class="package-info"><template v-if="loading"><span class="skeleton" /><span class="skeleton short" /></template><template v-else><strong :title="item.name">{{ item.name }}</strong><div class="package-meta"><span>{{ item.creator }}<template v-if="item.version !== undefined"> · v{{ item.version }}</template></span><span v-if="item.size_bytes !== undefined">{{ formatSize(item.size_bytes) }}</span></div></template></div><button type="button" class="card-hit-target" :aria-label="item.name" :aria-pressed="selected || checked" :disabled="loading" @click="emit('select')" @dblclick="emit('details')" @keydown.space.prevent="emit('details')" @keydown.enter.prevent="canLaunch ? emit('launch') : emit('select')"><span class="sr-only">{{ item.name }}</span></button><span v-if="!loading" class="package-type"><span />{{ t('resourceType.' + type) }}</span><span v-if="fresh" class="package-new">{{ t('ui.new') }}</span><label v-if="multiSelect" class="package-check cleanup-select" :class="{ checked }" @click.stop><input type="checkbox" :checked="checked" :aria-label="item.id" :disabled="disabled" @click.stop="emit('toggle', $event)" /></label><span v-else-if="missing" class="package-missing">{{ t('ui.missing', { count: missing }) }}</span><span v-else-if="favorite" class="package-favorite"><Icon name="star" :size="14" /></span><div v-if="!loading && !multiSelect" class="package-hover"><UiButton v-if="canLaunch" variant="primary" icon="play" icon-only size="lg" class="package-play" :aria-label="t('gameContent.launchScene')" @click.stop="emit('launch')" /><UiButton v-if="canFavorite" icon="star" icon-only class="image-action" :aria-label="t('ui.favorite')" @click.stop="emit('favorite')" /><UiButton icon="more" icon-only class="image-action" :aria-label="t('ui.more')" @click.stop="emit('more', $event)" /></div></article></template>
